function add(match, disposition, reason, opts={}) {
 const source=observed.find(r=>r.sourceUrl.includes(match)); if(!source)throw Error(match);
 const claims=(opts.quotes||[]).map(([id,text,facet='process',type='process-step',scopeKey=id])=>{text=text.replace(/[‐‑‒–—]/g,'-');if(!source.fullText.includes(text))throw Error('Quote not present: '+id);return {id,text,facet,type,scopeKey}});
 const actions=(opts.linkLabels||[]).map(label=>{const link=source.links.find(l=>l.label===label);if(!link)throw Error(label);return {label:opts.actionLabels?.[label]||label,url:link.url,actionType:'official-resource',evidence:{label:link.label,url:link.url,context:link.label,proofKind:'source-link-v1'}}});
 if(opts.selfAction)actions.push({label:opts.selfAction,url:source.sourceUrl,actionType:'official-resource',evidence:{label:source.title,url:source.sourceUrl,context:source.title,proofKind:'source-link-v1'}});
 records.push({sourceUrl:source.sourceUrl,title:opts.title||source.title,disposition,reason,checkedAt:source.checkedAt,contentHash:source.contentHash,hashScheme:source.hashScheme,documentFingerprint:source.documentFingerprint||undefined,sourceType:opts.sourceType||'services',authorityClass:opts.authorityClass||'official-page',fullText:source.fullText,claims,actions,withheldClaims:opts.withheldClaims||['All claims outside the explicit approved scope.'],verification:{retrievedUrl:source.finalUrl,currentness:opts.currentness||'Fetched the current official source on the recorded checkedAt date; no approval transfers to changed content.',completeness:opts.completeness||'Full main-content HTML fetched and normalized using the repository parser; all approved quotes were checked against the complete resulting text. Linked vendor content and private account state are not inferred.',replacementUrl:opts.replacementUrl||'',...(opts.references?{references:opts.references}:{})}});
}
