const report=records.find(r=>r.sourceUrl.includes('/2398/'));
const reportPages=report.fullText.split(/-- \d+ of 41 --/);
function reportExcerpt(page, start, end){
 const body=reportPages[page-1].trim();
 const first=start?body.indexOf(start):0;
 const last=end?body.indexOf(end,first)+end.length:body.length;
 if(first<0||last<end?.length||last<=first)throw Error('Missing reviewed report excerpt');
 const text=body.slice(first,last);
 if(!report.fullText.includes(text))throw Error('Report excerpt must be exact');
 return text;
}
